    az: { title: "Frontend və backend-in fərqi — Nibras Code", description: "Frontend adamın gördüyü üzüdür. Backend isə arxada qalan işdir. Üz düyməni göstərir. Arxa tərəf məlumatı saxlayır və yoxlayır. İkisi iki dil deyil. İkisi bir saytın iki yanıdır.", keywords: "frontend nədir, backend nədir, frontend backend fərqi, frontend və backend" },
